/// Test def_eq symmetry property.
///
/// Contract: `is_def_eq(a, b) == is_def_eq(b, a)` for all expressions.
/// This test verifies the symmetry claim in mod.rs:2309.
#[test]
fn test_is_def_eq_symmetry() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Test cases covering all Expr variants
    let exprs = vec![
        Expr::prop(),
        Expr::type_(),
        Expr::from_kind(ExprKind::Sort(Level::succ(Level::zero()))),
        Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(0)),
        Expr::pi(BinderInfo::Default, Expr::prop(), Expr::type_()),
        Expr::app(
            Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
            Expr::prop(),
        ),
        Expr::let_named(
            Name::anon(),
            Expr::type_(),
            Expr::prop(),
            Expr::bvar(0),
            false,
        ),
        Expr::from_kind(ExprKind::Lit(crate::Literal::Nat(crate::BigNat::Small(42)))),
        Expr::from_kind(ExprKind::Lit(crate::Literal::String("test".into()))),
    ];

    // Verify symmetry: for each pair (a, b), is_def_eq(a, b) == is_def_eq(b, a)
    for a in &exprs {
        for b in &exprs {
            let ab = tc.is_def_eq(a, b);
            let ba = tc.is_def_eq(b, a);
            assert_eq!(
                ab, ba,
                "Symmetry violated: is_def_eq({a:?}, {b:?}) = {ab}, is_def_eq({b:?}, {a:?}) = {ba}"
            );
        }
    }
}

/// Test def_eq transitivity property.
///
/// Contract: if `is_def_eq(a, b)` and `is_def_eq(b, c)` then `is_def_eq(a, c)`.
/// This test verifies the transitivity claim in mod.rs:2310.
#[test]
fn test_is_def_eq_transitivity() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Create chains of definitionally equal expressions via let reduction
    // let x := Prop in x  ==  Prop
    let let_prop = Expr::let_named(
        Name::anon(),
        Expr::type_(),
        Expr::prop(),
        Expr::bvar(0),
        false,
    );
    // let y := (let x := Prop in x) in y  ==  let x := Prop in x  ==  Prop
    let let_let_prop = Expr::let_named(
        Name::anon(),
        Expr::type_(),
        let_prop.clone(),
        Expr::bvar(0),
        false,
    );

    // Chain: let_let_prop == let_prop == Prop
    // Transitivity: if (a == b) and (b == c) then (a == c)
    let a = let_let_prop;
    let b = let_prop;
    let c = Expr::prop();

    assert!(tc.is_def_eq(&a, &b), "a == b should hold");
    assert!(tc.is_def_eq(&b, &c), "b == c should hold");
    assert!(
        tc.is_def_eq(&a, &c),
        "Transitivity violated: a == b and b == c but a != c"
    );

    // Another transitivity chain via beta reduction
    // (λ x. x) Prop  ==  Prop
    let id = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0));
    let app_id_prop = Expr::app(id.clone(), Expr::prop());
    // (λ x. x) ((λ y. y) Prop)  ==  (λ x. x) Prop  ==  Prop
    let app_id_app = Expr::app(id, app_id_prop.clone());

    assert!(
        tc.is_def_eq(&app_id_app, &app_id_prop),
        "app_id_app == app_id_prop"
    );
    assert!(
        tc.is_def_eq(&app_id_prop, &Expr::prop()),
        "app_id_prop == Prop"
    );
    assert!(
        tc.is_def_eq(&app_id_app, &Expr::prop()),
        "Transitivity: app_id_app == Prop"
    );
}

/// Regression: Pi body comparison must open binders so K-reduction can infer
/// the type of the equality proof binder (`h`) via local context.
///
/// Without binder opening, `cast h x` fails to reduce under Pi because `h`
/// remains `BVar(0)` and `try_infer_type_quick` cannot infer its type.
#[test]
fn test_is_def_eq_pi_opens_binder_for_cast_k_reduction() {
    let mut env = Environment::new();
    env.init_eq().expect("init_eq");
    let tc = TypeChecker::new(&env);

    let prop = Expr::prop();
    let level_one = Level::succ(Level::zero()); // Sort 1
    let sort_one = Expr::from_kind(ExprKind::Sort(level_one.clone()));
    let eq_prop_const = Expr::const_(Name::from_string("Eq"), vec![level_one.clone()]);
    let eq_sort_one_const = Expr::const_(
        Name::from_string("Eq"),
        vec![Level::succ(level_one.clone())],
    );
    let cast_const = Expr::const_(Name::from_string("cast"), vec![level_one]);

    // h : Eq (Sort 1) Prop Prop
    let h_ty = Expr::app(
        Expr::app(Expr::app(eq_sort_one_const, sort_one), prop.clone()),
        prop.clone(),
    );

    // Under binders Π (x : Prop), Π (h : Eq (Sort 1) Prop Prop), ...
    // x = BVar(1), h = BVar(0)
    let cast_h_x = Expr::app(
        Expr::app(
            Expr::app(Expr::app(cast_const, prop.clone()), prop.clone()),
            Expr::bvar(0),
        ),
        Expr::bvar(1),
    );

    let lhs_body = Expr::app(
        Expr::app(Expr::app(eq_prop_const.clone(), prop.clone()), cast_h_x),
        Expr::bvar(1),
    );
    let rhs_body = Expr::app(
        Expr::app(Expr::app(eq_prop_const, prop.clone()), Expr::bvar(1)),
        Expr::bvar(1),
    );

    let lhs = Expr::pi(
        BinderInfo::Default,
        prop.clone(),
        Expr::pi(BinderInfo::Default, h_ty.clone(), lhs_body),
    );
    let rhs = Expr::pi(
        BinderInfo::Default,
        prop.clone(),
        Expr::pi(BinderInfo::Default, h_ty, rhs_body),
    );

    assert!(
        tc.is_def_eq(&lhs, &rhs),
        "Pi binder comparison should open binders so cast h x reduces to x under K"
    );
}

