/// Sanity check for K-reduction path used by binder def_eq tests.
#[test]
fn test_whnf_cast_reduces_with_fvar_eq_proof() {
    let mut env = Environment::new();
    env.init_eq().expect("init_eq");
    let tc = TypeChecker::new(&env);

    let prop = Expr::prop();
    let level_one = Level::succ(Level::zero()); // Sort 1
    let sort_one = Expr::from_kind(ExprKind::Sort(level_one.clone()));
    let eq_sort_one_const = Expr::const_(
        Name::from_string("Eq"),
        vec![Level::succ(level_one.clone())],
    );
    let cast_const = Expr::const_(Name::from_string("cast"), vec![level_one.clone()]);

    // h : Eq (Sort 1) Prop Prop
    let h_ty = Expr::app(
        Expr::app(
            Expr::app(eq_sort_one_const.clone(), sort_one.clone()),
            prop.clone(),
        ),
        prop.clone(),
    );

    let x_id = tc
        .ctx
        .borrow_mut()
        .push(Name::from_string("x"), prop.clone(), BinderInfo::Default);
    let h_id = tc
        .ctx
        .borrow_mut()
        .push(Name::from_string("h"), h_ty, BinderInfo::Default);

    let cast_h_x = Expr::app(
        Expr::app(
            Expr::app(Expr::app(cast_const, prop.clone()), prop.clone()),
            Expr::fvar(h_id),
        ),
        Expr::fvar(x_id),
    );

    let x = Expr::fvar(x_id);
    let eq_refl_const = Expr::const_(
        Name::from_string("Eq.refl"),
        vec![Level::succ(level_one.clone())],
    );
    let h_refl = Expr::app(Expr::app(eq_refl_const, sort_one), prop.clone());
    let cast_refl_x = Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::const_(Name::from_string("cast"), vec![level_one]),
                    prop.clone(),
                ),
                prop.clone(),
            ),
            h_refl,
        ),
        x.clone(),
    );
    assert!(
        tc.is_def_eq(&cast_refl_x, &x),
        "cast (Eq.refl) x should reduce to x"
    );

    assert!(
        tc.is_def_eq(&cast_h_x, &x),
        "cast h x should def-eq x when h : Eq (Sort 1) Prop Prop is an FVar in local context"
    );
}

/// Test is_def_eq scaling behavior with cache.
///
/// This test documents the current scaling behavior of `is_def_eq` and ensures
/// the test suite doesn't hang due to slow algorithmic complexity.
///
/// The test uses wall-clock timing and takes the shared test lock to prevent
/// resource contention from causing false failures. See #1045.
///
/// NOTE: `is_def_eq` currently has worse-than-linear complexity on nested
/// lambdas and application chains. The underlying algorithmic issue is tracked
/// in #1052. This test uses small input sizes and does NOT assert on scaling
/// ratios since the known complexity issues would cause spurious failures.
/// Instead, it verifies correctness and documents observed timing.
#[test]
fn test_is_def_eq_scaling() {
    let _serial = crate::test_utils::serial_test_guard();
    run_with_timeout(SCALING_TEST_TIMEOUT, "test_is_def_eq_scaling", || {
        let env = Environment::new();
        // Test case 1: Deeply nested lambdas with shared type
        // Both expressions are structurally identical, so cache hits should dominate
        let type_expr = Expr::type_();
        // Small sizes to avoid timeout - complexity issue tracked in #1052
        let sizes = [3, 6, 12];
        let mut times_lam = Vec::new();

        for &n in &sizes {
            let tc = TypeChecker::new(&env); // Fresh cache each iteration
            let lam_a = build_nested_lam(n, &type_expr, Expr::bvar(0));
            let lam_b = build_nested_lam(n, &type_expr, Expr::bvar(0));

            let start = Instant::now();
            let result = tc.is_def_eq(&lam_a, &lam_b);
            let elapsed = start.elapsed();
            times_lam.push(elapsed.as_nanos());

            // Correctness check: identical expressions should be definitionally equal
            assert!(
                result,
                "Identical nested lambdas should be definitionally equal"
            );
        }

        // Document scaling but don't assert - known complexity issue (#1052)
        if times_lam[0] > 0 {
            let _ratio = times_lam[2] as f64 / times_lam[0].max(1) as f64;
            // eprintln!("is_def_eq nested lambdas: 4x input gave {_ratio:.1}x time");
        }

        // Test case 2: Application chains (more cache-intensive)
        let id_fn = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0));
        let arg = Expr::prop();
        let mut times_app = Vec::new();

        for &n in &sizes {
            let tc = TypeChecker::new(&env);
            let app_a = build_app_chain(n, id_fn.clone(), &arg);
            let app_b = build_app_chain(n, id_fn.clone(), &arg);

            let start = Instant::now();
            let result = tc.is_def_eq(&app_a, &app_b);
            let elapsed = start.elapsed();
            times_app.push(elapsed.as_nanos());

            // Correctness check: identical application chains should be equal
            assert!(
                result,
                "Identical application chains should be definitionally equal"
            );
        }

        // Document scaling but don't assert - known complexity issue (#1052)
        if times_app[0] > 0 {
            let _ratio = times_app[2] as f64 / times_app[0].max(1) as f64;
            // eprintln!("is_def_eq app chains: 4x input gave {_ratio:.1}x time");
        }

        // Test case 3: Compare DIFFERENT but structurally similar expressions
        // This tests cache efficiency when expressions differ
        let mut times_diff = Vec::new();

        for &n in &sizes {
            let tc = TypeChecker::new(&env);
            // Different body: bvar(0) vs bvar(1)
            let lam_a = build_nested_lam(n, &type_expr, Expr::bvar(0));
            let lam_b = build_nested_lam(n, &type_expr, Expr::bvar(1));

            let start = Instant::now();
            let result = tc.is_def_eq(&lam_a, &lam_b);
            let elapsed = start.elapsed();
            times_diff.push(elapsed.as_nanos());

            // Correctness check: different expressions should NOT be equal
            assert!(
                !result,
                "Different expressions should not be definitionally equal"
            );
        }

        // Document scaling but don't assert - known complexity issue (#1052)
        if times_diff[0] > 0 {
            let _ratio = times_diff[2] as f64 / times_diff[0].max(1) as f64;
            // eprintln!("is_def_eq different exprs: 4x input gave {_ratio:.1}x time");
        }
    });
}

/// Regression for #1491: lazy_delta_reduction should use quick literal checks
/// after unfolding and return `Ok(false)` for unequal literals.
#[test]
fn test_lazy_delta_different_defs_different_literals_false() {
    use crate::env::Declaration;
    use crate::expr::{BigNat, Literal};

    let mut env = Environment::new();

    env.add_decl(Declaration::Axiom {
        name: Name::from_string("Nat"),
        level_params: vec![],
        type_: Expr::type_(),
    })
    .expect("Nat axiom should add");
    let nat = Expr::const_(Name::from_string("Nat"), vec![]);

    env.add_decl(Declaration::Definition {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: nat.clone(),
        value: Expr::from_kind(ExprKind::Lit(Literal::Nat(BigNat::Small(42)))),
        is_reducible: true,
    })
    .expect("f definition should add");

    env.add_decl(Declaration::Definition {
        name: Name::from_string("g"),
        level_params: vec![],
        type_: nat,
        value: Expr::from_kind(ExprKind::Lit(Literal::Nat(BigNat::Small(43)))),
        is_reducible: true,
    })
    .expect("g definition should add");

    let tc = TypeChecker::new(&env);
    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    assert_eq!(
        tc.lazy_delta_reduction(&f, &g),
        Ok(false),
        "f := 42 and g := 43 should short-circuit to false after unfolding"
    );
}

/// Regression for #1491: lazy_delta_reduction should use quick Lam/Pi binding
/// checks after unfolding and return `Ok(true)` when domains are def-eq.
#[test]
fn test_lazy_delta_lam_quick_binding_check() {
    use crate::env::Declaration;

    let mut env = Environment::new();

    env.add_decl(Declaration::Definition {
        name: Name::from_string("A"),
        level_params: vec![],
        type_: Expr::type_(),
        value: Expr::prop(),
        is_reducible: true,
    })
    .expect("A definition should add");
    env.add_decl(Declaration::Definition {
        name: Name::from_string("B"),
        level_params: vec![],
        type_: Expr::type_(),
        value: Expr::prop(),
        is_reducible: true,
    })
    .expect("B definition should add");

    let a = Expr::const_(Name::from_string("A"), vec![]);
    let b = Expr::const_(Name::from_string("B"), vec![]);

    env.add_decl(Declaration::Definition {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, a.clone(), a.clone()),
        value: Expr::lam(BinderInfo::Default, a, Expr::bvar(0)),
        is_reducible: true,
    })
    .expect("f definition should add");
    env.add_decl(Declaration::Definition {
        name: Name::from_string("g"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, b.clone(), b.clone()),
        value: Expr::lam(BinderInfo::Default, b, Expr::bvar(0)),
        is_reducible: true,
    })
    .expect("g definition should add");

    let tc = TypeChecker::new(&env);
    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    assert_eq!(
        tc.lazy_delta_reduction(&f, &g),
        Ok(true),
        "quick Lam/Pi check should conclude equality inside lazy delta loop"
    );
}

/// Regression for #1491: is_def_eq_core entry should honor the same quick path
/// as Lean 4, including the equiv_manager fast hit.
#[test]
fn test_is_def_eq_core_entry_quick_uses_equiv_manager() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    let prop = Expr::prop();
    let type_ = Expr::type_();

    // Seed equivalence knowledge as if a prior successful def_eq query merged
    // this pair; recursive is_def_eq_core calls must consult this cache too.
    tc.equiv_manager.borrow_mut().add_equiv(&prop, &type_);

    assert!(
        tc.is_def_eq_core(&prop, &type_),
        "is_def_eq_core should short-circuit from equiv_manager before WHNF/delta phases"
    );
}

fn setup_reflection_box_env() -> (Environment, Name, Name) {
    use crate::env::Declaration;
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_bool().expect("init_bool should succeed");

    let box_name = Name::from_string("DefEqBoolBox");
    let box_ctor_name = Name::from_string("DefEqBoolBox.mk");
    let bool_type = Expr::const_(Name::from_string("Bool"), vec![]);

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: box_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: box_ctor_name.clone(),
                type_: Expr::pi(
                    BinderInfo::Default,
                    bool_type.clone(),
                    Expr::const_(box_name.clone(), vec![]),
                ),
            }],
        }],
    })
    .expect("DefEqBoolBox inductive should add");

    let closed_box_name = Name::from_string("DefEqBoolBox.closed");
    env.add_decl(Declaration::Definition {
        name: closed_box_name.clone(),
        level_params: vec![],
        type_: Expr::const_(box_name.clone(), vec![]),
        value: Expr::app(
            Expr::const_(box_ctor_name, vec![]),
            Expr::const_(Name::from_string("Bool.true"), vec![]),
        ),
        is_reducible: true,
    })
    .expect("DefEqBoolBox.closed definition should add");

    (env, box_name, closed_box_name)
}

/// Regression for #1662: closed reflection terms must use full WHNF at `is_def_eq_core` entry.
#[test]
fn test_is_def_eq_core_reflection_bool_true_closed_term() {
    let (env, box_name, closed_box_name) = setup_reflection_box_env();
    let tc = TypeChecker::new(&env);
    let bool_true = Expr::const_(Name::from_string("Bool.true"), vec![]);
    let reflected = Expr::proj(box_name, 0, Expr::const_(closed_box_name, vec![]));

    assert_eq!(
        tc.whnf(&reflected),
        bool_true,
        "sanity: reflected term should reduce to Bool.true under full WHNF"
    );
    assert!(
        tc.is_def_eq_core(&reflected, &bool_true),
        "is_def_eq_core should accept closed reflection term = Bool.true"
    );
    assert!(
        tc.is_def_eq_core(&bool_true, &reflected),
        "is_def_eq_core should accept Bool.true = closed reflection term"
    );
}

/// After #2150: let-bound FVar projections ARE definitionally equal to their reduced form.
///
/// The #2150 projection fix adds `try_unfold_proj_app` in the `(None, None)` lazy delta
/// case, which uses full WHNF to resolve the let-bound FVar and reduce the projection.
/// The old behavior (returning false) was a completeness gap — the terms are genuinely
/// definitionally equal since the FVar is let-bound.
#[test]
fn test_is_def_eq_core_reflection_let_bound_fvar_resolves() {
    let (env, box_name, closed_box_name) = setup_reflection_box_env();
    let tc = TypeChecker::new(&env);
    let bool_true = Expr::const_(Name::from_string("Bool.true"), vec![]);

    let local_box_id = tc.ctx.borrow_mut().push_let(
        Name::from_string("bx"),
        Expr::const_(box_name.clone(), vec![]),
        Expr::const_(closed_box_name, vec![]),
    );

    let reflected_open = Expr::proj(box_name, 0, Expr::fvar(local_box_id));
    assert_eq!(
        tc.whnf(&reflected_open),
        bool_true,
        "sanity: full WHNF can reduce the open term to Bool.true"
    );
    assert!(
        tc.is_def_eq_core(&reflected_open, &bool_true),
        "let-bound FVar projection should be def-eq to Bool.true after #2150 projection fix"
    );
}

/// Regression for #1662: truly open FVars (not let-bound) must NOT produce equality.
///
/// When the FVar has no let-value, WHNF cannot reduce the projection through it,
/// so `is_def_eq_core` correctly returns false.
#[test]
fn test_is_def_eq_core_reflection_truly_open_fvar_rejects() {
    let (env, box_name, _closed_box_name) = setup_reflection_box_env();
    let tc = TypeChecker::new(&env);
    let bool_true = Expr::const_(Name::from_string("Bool.true"), vec![]);

    // Push a local decl (not let-bound) — only has a type, no value.
    let open_box_id = tc.ctx.borrow_mut().push(
        Name::from_string("bx_open"),
        Expr::const_(box_name.clone(), vec![]),
        BinderInfo::Default,
    );

    let reflected_truly_open = Expr::proj(box_name, 0, Expr::fvar(open_box_id));
    assert!(
        !tc.is_def_eq_core(&reflected_truly_open, &bool_true),
        "projection through non-let-bound FVar must not be def-eq to Bool.true"
    );
}

/// Helper: add a reducible definition to the environment.
fn add_reducible(env: &mut Environment, name: &str, ty: Expr, value: Expr) {
    let mut info =
        crate::env::ConstantInfo::new(Name::from_string(name), vec![], ty, Some(value), true);
    info.reducibility = Reducibility::Reducible;
    env.extend_constants_unchecked(std::iter::once(info));
}

/// Regression for #1469 / #1464: is_def_eq_core must use post-delta forms (t_n/s_n)
/// from lazy_delta_reduction, not the pre-delta forms (a_n/b_n).
///
/// `f =?= g` where f:=h(p), g:=h(q), p:=Prop, q:=Prop, h is an axiom.
/// Delta unfolds f→(h p), g→(h q); loop exhausts (axiom head h → (None,None) → Err).
/// Post-delta structural comparison App(h,p)=?=App(h,q) succeeds (h=h, p=q via delta).
/// Pre-delta structural comparison Const("f")=?=Const("g") would fail ("f"≠"g").
///
/// The loop cannot resolve internally: h p≠h q structurally, quick_is_def_eq skips App,
/// and h:Type→Type avoids proof irrelevance.
///
/// Reference: Lean 4 type_checker.cpp:1094 updates t_n/s_n in place.
#[test]
fn test_is_def_eq_core_uses_post_delta_forms_not_pre_delta() {
    let mut env = Environment::new();

    // h : Type → Type (axiom — not delta-reducible, Type return avoids proof irrelevance)
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("postdelta_h"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::type_(), Expr::type_()),
    })
    .expect("postdelta_h axiom");

    // p, q : Type := Prop (reducible, same value — def-eq but different consts)
    add_reducible(&mut env, "postdelta_p", Expr::type_(), Expr::prop());
    add_reducible(&mut env, "postdelta_q", Expr::type_(), Expr::prop());

    let h = Expr::const_(Name::from_string("postdelta_h"), vec![]);
    let p = Expr::const_(Name::from_string("postdelta_p"), vec![]);
    let q = Expr::const_(Name::from_string("postdelta_q"), vec![]);

    // f := h p, g := h q (reducible — values have axiom head, not caught by delta loop)
    add_reducible(
        &mut env,
        "postdelta_f",
        Expr::type_(),
        Expr::app(h.clone(), p),
    );
    add_reducible(&mut env, "postdelta_g", Expr::type_(), Expr::app(h, q));

    let tc = TypeChecker::new(&env);
    let f = Expr::const_(Name::from_string("postdelta_f"), vec![]);
    let g = Expr::const_(Name::from_string("postdelta_g"), vec![]);

    // Sanity: lazy_delta_reduction should exhaust (return Err) with post-delta forms
    assert!(
        tc.lazy_delta_reduction(&f, &g).is_err(),
        "lazy_delta_reduction must exhaust for f/g whose values have axiom heads"
    );

    // Core assertion: f and g are def-eq through post-delta structural comparison
    assert!(
        tc.is_def_eq(&f, &g),
        "f := h p and g := h q must be def-eq (p = q = Prop); \
         requires post-delta forms from lazy_delta_reduction"
    );
    assert!(
        tc.is_def_eq(&g, &f),
        "post-delta propagation must be symmetric"
    );
}

/// Test MData asymmetric equality: MData wrapping an expression should be
/// def-eq to the unwrapped expression. MData is transparent for definitional
/// equality — the metadata is ignored.
///
/// Boundary: `quick_is_def_eq` only handles the (MData, MData) case directly.
/// Asymmetric cases (MData vs non-MData) must be resolved by Phase 1 WHNF
/// stripping MData via `whnf_core_no_delta`.
#[test]
fn test_def_eq_mdata_asymmetric() {
    use crate::expr::MDataValue;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    let bare = Expr::nat_lit(42);
    let wrapped = Expr::mdata(
        vec![(Name::from_string("tag"), MDataValue::Nat(1))],
        Expr::nat_lit(42),
    );

    // Asymmetric: bare vs wrapped
    assert!(
        tc.is_def_eq(&bare, &wrapped),
        "MData(tag, 42) must be def-eq to 42 (asymmetric, MData is transparent)"
    );
    assert!(
        tc.is_def_eq(&wrapped, &bare),
        "Symmetry: 42 must be def-eq to MData(tag, 42)"
    );

    // Asymmetric with non-literal: Prop wrapped in MData
    let prop_bare = Expr::prop();
    let prop_wrapped = Expr::mdata(
        vec![(Name::from_string("info"), MDataValue::Nat(0))],
        Expr::prop(),
    );
    assert!(
        tc.is_def_eq(&prop_bare, &prop_wrapped),
        "MData-wrapped Prop must be def-eq to bare Prop"
    );

    // Double-wrapped MData
    let double_wrapped = Expr::mdata(
        vec![(Name::from_string("outer"), MDataValue::Nat(2))],
        wrapped.clone(),
    );
    assert!(
        tc.is_def_eq(&bare, &double_wrapped),
        "Double-wrapped MData must be def-eq to bare expression"
    );
}

/// Succ-peel across a grind-stuck `Nat.add` — the Char/Ordinal succ-peel class.
///
/// `native_nat_binop_grind_stuck` leaves `Nat.add x <closed k >= 512>` unreduced
/// (never delta-unfolded into its Θ(k) unary `Nat.rec` grind), which also hides
/// the add's leading successor from `is_def_eq_offset`'s structural peel. The
/// `nat_add_succ_pred` companion must expose exactly one successor when the
/// OPPOSITE side is a genuine `Nat.succ`, closing the live-traced pair behind
/// `Char.ofOrdinal._proof_3` / `Char.ordinal_ofOrdinal._proof_1_1`:
/// `x + 2049 =?= Nat.succ (x + 2048)` (Lean closes it by full ι-reduction).
#[test]
fn test_def_eq_offset_stuck_add_peels_against_genuine_succ() {
    let mut env = Environment::new();
    env.init_nat().expect("init_nat");
    let tc = TypeChecker::new(&env);

    let nat_ty = Expr::const_(Name::from_string("Nat"), vec![]);
    let x_id = tc
        .ctx
        .borrow_mut()
        .push(Name::from_string("x"), nat_ty, BinderInfo::Default);
    let x = Expr::fvar(x_id);
    let add = |a: Expr, b: Expr| {
        Expr::app(
            Expr::app(Expr::const_(Name::from_string("Nat.add"), vec![]), a),
            b,
        )
    };
    let succ = |a: Expr| Expr::app(Expr::const_(Name::from_string("Nat.succ"), vec![]), a);

    // Both counts sit at/above the 512 grind-stuck threshold: without the peel,
    // the left side stays `Nat.add`-headed and the succ-vs-add pair falls
    // through to a structural mismatch (the pre-fix Char/Ordinal failure).
    let lhs = add(x.clone(), Expr::nat_lit(2049));
    let rhs = succ(add(x.clone(), Expr::nat_lit(2048)));
    assert!(
        tc.is_def_eq(&lhs, &rhs),
        "stuck `x + 2049` must peel one hidden succ against `Nat.succ (x + 2048)`"
    );
    assert!(
        tc.is_def_eq(&rhs, &lhs),
        "`Nat.succ (x + 2048)` =?= stuck `x + 2049` (symmetry)"
    );

    // Below the threshold the add unfolds as before; the peel must agree.
    let small_lhs = add(x.clone(), Expr::nat_lit(1));
    let small_rhs = succ(x.clone());
    assert!(
        tc.is_def_eq(&small_lhs, &small_rhs),
        "`x + 1` must remain def-eq to `Nat.succ x`"
    );

    // A fully CLOSED add must stay with `reduce_nat` (O(1)): the peel declines
    // on fvar-free adds, so a 2^32-scale count cannot recurse Θ(count) into a
    // heartbeat-exhausted wrong reject. Verdict: accept, instantly.
    let closed_lhs = add(Expr::nat_lit(7), Expr::nat_lit(4_294_967_296));
    let closed_rhs = Expr::nat_lit(4_294_967_303);
    assert!(
        tc.is_def_eq(&closed_lhs, &closed_rhs),
        "closed `7 + 2^32` must reduce to `2^32 + 7` via reduce_nat, not the peel"
    );
}

/// Negative control for the stuck-add succ-peel: peeling must preserve the
/// verdict exactly — differing counts stay NOT def-eq, and a zero count (no
/// predecessor) must not peel at all.
#[test]
fn test_def_eq_offset_stuck_add_peel_rejects_unequal_counts() {
    let mut env = Environment::new();
    env.init_nat().expect("init_nat");
    let tc = TypeChecker::new(&env);

    let nat_ty = Expr::const_(Name::from_string("Nat"), vec![]);
    let x_id = tc
        .ctx
        .borrow_mut()
        .push(Name::from_string("x"), nat_ty, BinderInfo::Default);
    let x = Expr::fvar(x_id);
    let add = |a: Expr, b: Expr| {
        Expr::app(
            Expr::app(Expr::const_(Name::from_string("Nat.add"), vec![]), a),
            b,
        )
    };
    let succ = |a: Expr| Expr::app(Expr::const_(Name::from_string("Nat.succ"), vec![]), a);

    // x + 2049 vs succ (x + 2047): peel exposes `x + 2048` vs `x + 2047`,
    // which must stay unequal (no add-vs-add cascade re-peels them).
    let lhs = add(x.clone(), Expr::nat_lit(2049));
    let rhs = succ(add(x.clone(), Expr::nat_lit(2047)));
    assert!(
        !tc.is_def_eq(&lhs, &rhs),
        "`x + 2049` must NOT be def-eq to `Nat.succ (x + 2047)`"
    );

    // x + 0 vs succ x: count 0 has no predecessor, so the peel declines and
    // the ordinary pipeline decides (x + 0 ι-reduces to x, x != succ x).
    let zero_lhs = add(x.clone(), Expr::nat_lit(0));
    let zero_rhs = succ(x.clone());
    assert!(
        !tc.is_def_eq(&zero_lhs, &zero_rhs),
        "`x + 0` must NOT be def-eq to `Nat.succ x`"
    );
}

/// Test that Nat zero is recognized in both representations: literal 0
/// and Const("Nat.zero"). These must be def-eq through `is_def_eq_offset`
/// in the lazy delta reduction loop.
///
/// Boundary: `is_nat_zero_expr` checks both `BigNat::Small(0)` and
/// `Const(Nat.zero, [])`. Cross-representation must work.
#[test]
fn test_def_eq_nat_zero_cross_representation() {
    let mut env = Environment::new();
    env.init_nat().unwrap();
    let tc = TypeChecker::new(&env);

    let lit_zero = Expr::nat_lit(0);
    let const_zero = Expr::const_(Name::from_string("Nat.zero"), vec![]);

    assert!(
        tc.is_def_eq(&lit_zero, &const_zero),
        "Nat literal 0 must be def-eq to Nat.zero constant"
    );
    assert!(
        tc.is_def_eq(&const_zero, &lit_zero),
        "Nat.zero constant must be def-eq to literal 0 (symmetry)"
    );
}

/// Test that `is_def_eq_offset` correctly handles Nat.succ(0) vs literal 1.
///
/// Boundary: `is_nat_succ_expr` on `Lit(Nat(1))` returns `Lit(Nat(0))`.
/// `Nat.succ(Nat.zero)` is `App(Const(Nat.succ), Const(Nat.zero))` which
/// returns `Const(Nat.zero)`. Then `is_def_eq_core` compares `Lit(0)` vs
/// `Const(Nat.zero)`, which must succeed through `is_def_eq_offset` again.
#[test]
fn test_def_eq_nat_succ_cross_representation() {
    let mut env = Environment::new();
    env.init_nat().unwrap();
    let tc = TypeChecker::new(&env);

    let lit_one = Expr::nat_lit(1);
    let succ_zero = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        Expr::const_(Name::from_string("Nat.zero"), vec![]),
    );

    assert!(
        tc.is_def_eq(&lit_one, &succ_zero),
        "Literal 1 must be def-eq to Nat.succ(Nat.zero)"
    );
    assert!(
        tc.is_def_eq(&succ_zero, &lit_one),
        "Nat.succ(Nat.zero) must be def-eq to literal 1 (symmetry)"
    );

    // Deeper: literal 2 vs Nat.succ(Nat.succ(Nat.zero))
    let lit_two = Expr::nat_lit(2);
    let succ_succ_zero = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        succ_zero.clone(),
    );

    assert!(
        tc.is_def_eq(&lit_two, &succ_succ_zero),
        "Literal 2 must be def-eq to Nat.succ(Nat.succ(Nat.zero))"
    );
}

/// Test that binding comparison (Lam/Pi) works when domains require delta
/// reduction to prove equal. This exercises the critical path where
/// `quick_is_def_eq` returns `Some(result)` for binding forms and the
/// domain comparison uses full recursive `is_def_eq_impl`.
///
/// Boundary: `is_def_eq_binding_impl` calls `is_def_eq_impl(ty1, ty2)`
/// which triggers lazy delta reduction for the domains.
#[test]
fn test_def_eq_binding_domains_need_delta() {
    let mut env = Environment::new();

    // Define A := Prop (reducible)
    env.add_decl(Declaration::Definition {
        name: Name::from_string("A_alias"),
        level_params: vec![],
        type_: Expr::type_(),
        value: Expr::prop(),
        is_reducible: true,
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let a_alias = Expr::const_(Name::from_string("A_alias"), vec![]);

    // (λ x : A_alias. x) vs (λ x : Prop. x)
    // Domains: A_alias =?= Prop requires delta to unfold A_alias
    let lam_with_alias = Expr::lam(BinderInfo::Default, a_alias.clone(), Expr::bvar(0));
    let lam_with_prop = Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(0));

    assert!(
        tc.is_def_eq(&lam_with_alias, &lam_with_prop),
        "Lambda with A_alias domain must be def-eq to lambda with Prop domain"
    );

    // Same for Pi types
    let pi_with_alias = Expr::pi(BinderInfo::Default, a_alias, Expr::type_());
    let pi_with_prop = Expr::pi(BinderInfo::Default, Expr::prop(), Expr::type_());

    assert!(
        tc.is_def_eq(&pi_with_alias, &pi_with_prop),
        "Pi with A_alias domain must be def-eq to Pi with Prop domain"
    );
}

/// Test that `is_def_eq_offset` returns None (not false) when comparing
/// Nat.zero against Nat.succ(x). This must fall through to other equality
/// checks, not prematurely return false.
///
/// Boundary: `is_def_eq_offset` returns `Some(true)` for zero=zero,
/// `Some(result)` for succ=succ, but `None` for zero≠succ. The None
/// causes `lazy_delta_reduction` to continue the loop.
#[test]
fn test_def_eq_nat_zero_vs_succ_not_premature_false() {
    let mut env = Environment::new();
    env.init_nat().unwrap();
    let tc = TypeChecker::new(&env);

    // 0 vs 1 — should be NOT def-eq (different values)
    let zero = Expr::nat_lit(0);
    let one = Expr::nat_lit(1);
    assert!(
        !tc.is_def_eq(&zero, &one),
        "Nat 0 and Nat 1 must NOT be def-eq"
    );

    // 0 vs Nat.succ(0) — should be NOT def-eq
    let succ_zero = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        Expr::nat_lit(0),
    );
    assert!(
        !tc.is_def_eq(&zero, &succ_zero),
        "Nat 0 and Nat.succ(0) must NOT be def-eq"
    );

    // Nat.zero vs Nat.succ(Nat.zero) — also NOT def-eq
    let const_zero = Expr::const_(Name::from_string("Nat.zero"), vec![]);
    let succ_const_zero = Expr::app(
        Expr::const_(Name::from_string("Nat.succ"), vec![]),
        const_zero.clone(),
    );
    assert!(
        !tc.is_def_eq(&const_zero, &succ_const_zero),
        "Nat.zero and Nat.succ(Nat.zero) must NOT be def-eq"
    );
}

/// Regression test for #1773: FVarId-unreachability invariant across push/pop.
///
/// Validates that def_eq results cached during a scope (with FVars) do not
/// produce incorrect results after the scope is popped. The invariant is:
/// Regression test: `local_context_mut()` must clear all def_eq and whnf caches.
///
/// Populates caches via def_eq queries, then asserts they are emptied after
/// `local_context_mut()` modifies the context (push/pop).
#[test]
fn test_def_eq_scope_cache_clearing_contract() {
    let env = Environment::new();
    let mut tc = TypeChecker::new(&env);
    let nat_ty = Expr::const_(Name::from_string("Nat"), vec![]);

    let fvar_id1 =
        tc.local_context_mut()
            .push(Name::from_string("x"), nat_ty.clone(), BinderInfo::Default);
    let fvar1 = Expr::fvar(fvar_id1);

    // Populate caches.
    assert!(
        tc.is_def_eq(&fvar1, &fvar1),
        "FVar should be def-eq with itself"
    );
    let lit = Expr::nat_lit(42);
    assert!(
        !tc.is_def_eq(&fvar1, &lit),
        "FVar should not be def-eq with literal"
    );

    let def_eq_before = tc.def_eq_cache_entries();
    let whnf_before = tc.whnf_cache_entries();
    assert!(
        def_eq_before > 0 || whnf_before > 0,
        "Caches should be populated (def_eq={def_eq_before}, whnf={whnf_before})"
    );

    // Pop clears caches via local_context_mut().
    tc.local_context_mut().pop();

    assert_eq!(
        tc.def_eq_cache_entries(),
        0,
        "def_eq cache must be cleared (was {def_eq_before})"
    );
    assert_eq!(
        tc.whnf_cache_entries(),
        0,
        "whnf cache must be cleared (was {whnf_before})"
    );
}

/// After scope pop + push, new FVars must not be affected by stale cache entries.
///
/// FVarIds are monotonically increasing, so expressions containing popped FVars
/// are never queried again. This test verifies correctness in a fresh scope.
#[test]
fn test_def_eq_fresh_scope_after_pop_no_stale_cache() {
    let env = Environment::new();
    let mut tc = TypeChecker::new(&env);
    let nat_ty = Expr::const_(Name::from_string("Nat"), vec![]);
    let lit = Expr::nat_lit(42);

    // Scope 1: populate caches then pop.
    let fvar_id1 =
        tc.local_context_mut()
            .push(Name::from_string("x"), nat_ty.clone(), BinderInfo::Default);
    let fvar1 = Expr::fvar(fvar_id1);
    assert!(
        tc.is_def_eq(&fvar1, &fvar1),
        "fvar x should be def-eq to itself"
    );
    assert!(
        !tc.is_def_eq(&fvar1, &lit),
        "fvar x should not be def-eq to nat_lit 42"
    );
    tc.local_context_mut().pop();

    // Scope 2: fresh local.
    let fvar_id2 =
        tc.local_context_mut()
            .push(Name::from_string("y"), nat_ty.clone(), BinderInfo::Default);
    assert_ne!(
        fvar_id1, fvar_id2,
        "FVarIds must be monotonically increasing"
    );
    let fvar2 = Expr::fvar(fvar_id2);

    assert!(
        tc.is_def_eq(&fvar2, &fvar2),
        "New FVar should be def-eq with itself"
    );
    assert!(
        !tc.is_def_eq(&fvar2, &lit),
        "New FVar should not be def-eq with literal"
    );
    assert!(
        !tc.is_def_eq(&fvar1, &fvar2),
        "Popped FVar must not be def-eq with active FVar"
    );

    let app1 = Expr::app(fvar2.clone(), Expr::nat_lit(0));
    let app2 = Expr::app(fvar2.clone(), Expr::nat_lit(0));
    assert!(
        tc.is_def_eq(&app1, &app2),
        "Identical app expressions should be def-eq"
    );

    tc.local_context_mut().pop();
}

/// Regression test for #1773: lazy_delta_reduction iteration cap.
///
/// Verifies that the iteration cap does not interfere with normal operation.
/// Normal def-eq comparisons should complete well within the 10,000 cap.
#[test]
fn test_lazy_delta_reduction_iteration_cap_normal_operation() {
    let mut env = Environment::new();

    // Create a chain of definitions: f0 = Nat, f1 = f0, f2 = f1, ...
    // This exercises the lazy delta reduction loop with multiple unfold steps.
    let nat_type = Expr::const_(Name::from_string("Nat"), vec![]);
    let mut prev_name = Name::from_string("Nat");

    for i in 0..50 {
        let _i = i; // suppress unused warning
        let name = Name::from_string(&format!("chain_{i}"));
        let value = Expr::const_(prev_name.clone(), vec![]);
        env.add_decl_unchecked(Declaration::Definition {
            name: name.clone(),
            level_params: vec![],
            type_: Expr::sort(Level::succ(Level::zero())),
            value,
            is_reducible: false,
        });
        prev_name = name;
    }

    let tc = TypeChecker::new(&env);

    // chain_49 should be def-eq to Nat after 50 unfolding steps.
    let chain_end = Expr::const_(prev_name, vec![]);
    assert!(
        tc.is_def_eq(&chain_end, &nat_type),
        "chain_49 should unfold to Nat through 50 delta steps"
    );
}

/// Test that `lazy_delta_proj_reduction` handles inner delta unfolding.
///
/// Constructs `Proj(S, 0, pa) =?= Proj(S, 0, pb)` where `pa` and `pb` are
/// definitions that both unfold to `S.mk(Bool.true)`. The projection-specific
/// delta loop should unfold `pa` and `pb`, find them equal, and return true
/// without needing to extract fields.
///
/// Part of #1465 — tests Phase 4 projection comparison with lazy delta.
#[test]
fn test_lazy_delta_proj_reduction_inner_delta() {
    use crate::env::Declaration;
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_bool().expect("init_bool should succeed");

    let s_name = Name::from_string("ProjDeltaS");
    let s_ctor_name = Name::from_string("ProjDeltaS.mk");
    let bool_type = Expr::const_(Name::from_string("Bool"), vec![]);

    // Structure: `ProjDeltaS` with one Bool field
    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: s_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: s_ctor_name.clone(),
                type_: Expr::pi(
                    BinderInfo::Default,
                    bool_type,
                    Expr::const_(s_name.clone(), vec![]),
                ),
            }],
        }],
    })
    .expect("ProjDeltaS inductive should add");

    let mk_true = Expr::app(
        Expr::const_(s_ctor_name, vec![]),
        Expr::const_(Name::from_string("Bool.true"), vec![]),
    );

    // def pa : ProjDeltaS := ProjDeltaS.mk Bool.true
    env.add_decl(Declaration::Definition {
        name: Name::from_string("pa"),
        level_params: vec![],
        type_: Expr::const_(s_name.clone(), vec![]),
        value: mk_true.clone(),
        is_reducible: true,
    })
    .expect("pa definition should add");

    // def pb : ProjDeltaS := ProjDeltaS.mk Bool.true
    env.add_decl(Declaration::Definition {
        name: Name::from_string("pb"),
        level_params: vec![],
        type_: Expr::const_(s_name.clone(), vec![]),
        value: mk_true,
        is_reducible: true,
    })
    .expect("pb definition should add");

    let tc = TypeChecker::new(&env);

    let proj_pa = Expr::proj(
        s_name.clone(),
        0,
        Expr::const_(Name::from_string("pa"), vec![]),
    );
    let proj_pb = Expr::proj(s_name, 0, Expr::const_(Name::from_string("pb"), vec![]));

    assert!(
        tc.is_def_eq(&proj_pa, &proj_pb),
        "Proj(S, 0, pa) =?= Proj(S, 0, pb) should succeed: \
         lazy_delta_proj_reduction unfolds pa and pb to the same constructor app"
    );
}

/// Test that `lazy_delta_proj_reduction` falls back to field extraction
/// via `reduce_proj_core` when inner expressions are structurally different.
///
/// Constructs `Proj(S, 0, pa) =?= Proj(S, 0, pb)` where `pa` unfolds to
/// `S.mk(Bool.true)` and `pb` unfolds to `S.mk(Bool.false)`. After unfolding,
/// the constructor heads are not delta-reducible so the loop returns
/// `DefUnknown`. Then `reduce_proj_core` extracts field 0 from each
/// constructor app, giving `Bool.true =?= Bool.false` which is false.
///
/// Part of #1465 — tests the reduce_proj_core fallback path.
#[test]
fn test_lazy_delta_proj_reduction_field_extraction_fallback() {
    use crate::env::Declaration;
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_bool().expect("init_bool should succeed");

    let s_name = Name::from_string("ProjFieldS");
    let s_ctor_name = Name::from_string("ProjFieldS.mk");
    let bool_type = Expr::const_(Name::from_string("Bool"), vec![]);

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: s_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: s_ctor_name.clone(),
                type_: Expr::pi(
                    BinderInfo::Default,
                    bool_type,
                    Expr::const_(s_name.clone(), vec![]),
                ),
            }],
        }],
    })
    .expect("ProjFieldS inductive should add");

    // def pa : ProjFieldS := ProjFieldS.mk Bool.true
    env.add_decl(Declaration::Definition {
        name: Name::from_string("pfa"),
        level_params: vec![],
        type_: Expr::const_(s_name.clone(), vec![]),
        value: Expr::app(
            Expr::const_(s_ctor_name.clone(), vec![]),
            Expr::const_(Name::from_string("Bool.true"), vec![]),
        ),
        is_reducible: true,
    })
    .expect("pfa definition should add");

    // def pb : ProjFieldS := ProjFieldS.mk Bool.false
    env.add_decl(Declaration::Definition {
        name: Name::from_string("pfb"),
        level_params: vec![],
        type_: Expr::const_(s_name.clone(), vec![]),
        value: Expr::app(
            Expr::const_(s_ctor_name, vec![]),
            Expr::const_(Name::from_string("Bool.false"), vec![]),
        ),
        is_reducible: true,
    })
    .expect("pfb definition should add");

    let tc = TypeChecker::new(&env);

    let proj_pa = Expr::proj(
        s_name.clone(),
        0,
        Expr::const_(Name::from_string("pfa"), vec![]),
    );
    let proj_pb = Expr::proj(s_name, 0, Expr::const_(Name::from_string("pfb"), vec![]));

    assert!(
        !tc.is_def_eq(&proj_pa, &proj_pb),
        "Proj(S, 0, pfa) =?= Proj(S, 0, pfb) should fail: \
         reduce_proj_core extracts Bool.true vs Bool.false"
    );
}

/// Negative test for #1773: lazy_delta_reduction iteration cap fires.
///
/// Creates a chain of 10,050 definitions where chain_N = chain_{N-1}.
/// Comparing chain_10049 with the base value requires > 10,000 unfolding
/// steps, which exceeds `MAX_LAZY_DELTA_ITERATIONS`. The cap should fire
/// and conservatively return false (not def-eq), preventing unbounded looping.
///
/// This is the safety net against adversarial .olean files that could cause
/// non-termination via deeply nested definition chains.
#[test]
fn test_lazy_delta_reduction_iteration_cap_fires() {
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Base: Nat axiom so we have a type to reference.
    env.add_decl_unchecked(Declaration::Axiom {
        name: Name::from_string("Nat"),
        level_params: vec![],
        type_: Expr::sort(Level::succ(Level::zero())),
    });

    let chain_len: u32 = 10_050;
    let base_name = Name::from_string("Nat");
    let type_ = Expr::sort(Level::succ(Level::zero()));
    let mut prev_name = base_name.clone();

    for i in 0..chain_len {
        let name = Name::from_string(&format!("deep_chain_{i}"));
        let value = Expr::const_(prev_name.clone(), vec![]);
        env.add_decl_unchecked(Declaration::Definition {
            name: name.clone(),
            level_params: vec![],
            type_: type_.clone(),
            value,
            is_reducible: false,
        });
        prev_name = name;
    }

    let tc = TypeChecker::new(&env);

    // Comparing the end of the chain with the base requires 10,050 steps.
    // The iteration cap (10,000) should fire, returning false conservatively.
    let chain_end = Expr::const_(prev_name, vec![]);
    let base = Expr::const_(base_name, vec![]);
    assert!(
        !tc.is_def_eq(&chain_end, &base),
        "chain of {} definitions should exceed the 10,000 iteration cap \
         and return false (not def-eq) rather than looping unboundedly",
        chain_len
    );
}

/// Negative test for #1773: `lazy_delta_proj_reduction` iteration cap fires.
///
/// Same principle as `test_lazy_delta_reduction_iteration_cap_fires`, but
/// exercises the projection-specific delta loop (`MAX_PROJ_DELTA_ITERATIONS`).
///
/// Creates a chain of 10,050 definitions where chain_N = chain_{N-1}, and
/// calls `lazy_delta_proj_reduction` directly to verify the cap fires after
/// 10,000 iterations and returns false conservatively.
///
/// Note: this cap is defense-in-depth — `is_def_eq_core` Phase 2 resolves
/// Proj expressions via `try_unfold_proj_app` (full whnf_core including delta)
/// before Phase 4's `lazy_delta_proj_reduction` is reached. Therefore, the
/// cap can only be tested by calling the function directly.
#[test]
fn test_lazy_delta_proj_reduction_iteration_cap_fires() {
    use crate::env::Declaration;

    let mut env = Environment::new();

    // Base: Nat axiom
    env.add_decl_unchecked(Declaration::Axiom {
        name: Name::from_string("Nat"),
        level_params: vec![],
        type_: Expr::sort(Level::succ(Level::zero())),
    });

    let chain_len: u32 = 10_050;
    let base_name = Name::from_string("Nat");
    let type_ = Expr::sort(Level::succ(Level::zero()));
    let mut prev_name = base_name.clone();

    for i in 0..chain_len {
        let name = Name::from_string(&format!("proj_cap_chain_{i}"));
        let value = Expr::const_(prev_name.clone(), vec![]);
        env.add_decl_unchecked(Declaration::Definition {
            name: name.clone(),
            level_params: vec![],
            type_: type_.clone(),
            value,
            is_reducible: false,
        });
        prev_name = name;
    }

    let tc = TypeChecker::new(&env);

    // Call lazy_delta_proj_reduction directly with the chain end and base.
    // The function runs lazy_delta_reduction_step in a loop on the inner
    // expressions. With 10,050 links, it needs >10,000 steps to resolve.
    // MAX_PROJ_DELTA_ITERATIONS (10,000) fires first → conservative false.
    let chain_end = Expr::const_(prev_name, vec![]);
    let base = Expr::const_(base_name, vec![]);
    assert!(
        !tc.lazy_delta_proj_reduction(&chain_end, &base, 0),
        "chain of {} definitions should exceed the 10,000 \
         MAX_PROJ_DELTA_ITERATIONS cap and return false (not def-eq) \
         rather than looping unboundedly",
        chain_len
    );
}

/// Build an environment with Bool and a 1-field structure `{prefix}S` with
/// constructor `{prefix}S.mk` taking a Bool. Returns `(env, struct_name)`.
fn make_bool_struct_env(prefix: &str) -> (Environment, Name) {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    env.init_bool().expect("init_bool should succeed");

    let s_name = Name::from_string(&format!("{prefix}S"));
    let s_ctor_name = Name::from_string(&format!("{prefix}S.mk"));
    let bool_type = Expr::const_(Name::from_string("Bool"), vec![]);
    let s_type = Expr::const_(s_name.clone(), vec![]);

    env.add_inductive(InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: s_name.clone(),
            type_: Expr::type_(),
            constructors: vec![Constructor {
                name: s_ctor_name,
                type_: Expr::pi(BinderInfo::Default, bool_type, s_type),
            }],
        }],
    })
    .expect("inductive should add");
    (env, s_name)
}

/// Add a non-reducible definition to the environment.
fn add_def(env: &mut Environment, name: &str, type_: Expr, value: Expr) {
    env.add_decl_unchecked(Declaration::Definition {
        name: Name::from_string(name),
        level_params: vec![],
        type_,
        value,
        is_reducible: false,
    });
}

/// Test that `lazy_delta_proj_reduction` correctly handles height-based
/// ordering when inner expressions have different definition heights.
///
/// Creates definitions at heights 1, 2, and 3, then compares projections.
/// The lazy delta loop unfolds the higher-height definition first, matching
/// Lean 4 type_checker.cpp:911-915.
///
/// Part of #1507 — tests height-based lazy delta ordering for projections.
#[test]
fn test_lazy_delta_proj_reduction_height_ordering() {
    let (mut env, s_name) = make_bool_struct_env("HeightProj");
    let s_type = Expr::const_(s_name.clone(), vec![]);
    let ctor_name = Name::from_string("HeightProjS.mk");

    let mk_true = Expr::app(
        Expr::const_(ctor_name, vec![]),
        Expr::const_(Name::from_string("Bool.true"), vec![]),
    );

    // base (height 1) -> mid (height 2) -> top (height 3)
    add_def(&mut env, "hp_base", s_type.clone(), mk_true);
    add_def(
        &mut env,
        "hp_mid",
        s_type.clone(),
        Expr::const_(Name::from_string("hp_base"), vec![]),
    );
    add_def(
        &mut env,
        "hp_top",
        s_type,
        Expr::const_(Name::from_string("hp_mid"), vec![]),
    );

    let tc = TypeChecker::new(&env);

    // Proj(S, 0, top) =?= Proj(S, 0, base): heights 3 vs 1
    let proj_top = Expr::proj(
        s_name.clone(),
        0,
        Expr::const_(Name::from_string("hp_top"), vec![]),
    );
    let proj_base = Expr::proj(
        s_name.clone(),
        0,
        Expr::const_(Name::from_string("hp_base"), vec![]),
    );
    assert!(
        tc.is_def_eq(&proj_top, &proj_base),
        "Proj(S, 0, top) =?= Proj(S, 0, base) should succeed via height-ordered lazy delta"
    );

    // Asymmetric: Proj(S, 0, mid) =?= Proj(S, 0, top)
    let proj_mid = Expr::proj(s_name, 0, Expr::const_(Name::from_string("hp_mid"), vec![]));
    assert!(
        tc.is_def_eq(&proj_mid, &proj_top),
        "Proj(S, 0, mid) =?= Proj(S, 0, top) should succeed: asymmetric heights"
    );
}

/// Test that `lazy_delta_proj_reduction` avoids unnecessary reduction when
/// equal-height aliases unfold to the same expression in one step.
///
/// Both aliases have height 2 and unfold to the same height-1 definition.
/// The lazy delta loop finds equality after one step without reducing to
/// the constructor. WHNF call counting confirms minimal work.
///
/// Part of #1507 — tests early-exit optimization in lazy_delta_proj_reduction.
#[test]
fn test_lazy_delta_proj_reduction_early_equality() {
    let (mut env, s_name) = make_bool_struct_env("EarlyEq");
    let s_type = Expr::const_(s_name.clone(), vec![]);
    let ctor_name = Name::from_string("EarlyEqS.mk");

    let mk_true = Expr::app(
        Expr::const_(ctor_name, vec![]),
        Expr::const_(Name::from_string("Bool.true"), vec![]),
    );

    // alias1 (height 1) -> alias_a (height 2), alias_b (height 2)
    add_def(&mut env, "eq_alias1", s_type.clone(), mk_true);
    let alias1_ref = Expr::const_(Name::from_string("eq_alias1"), vec![]);
    add_def(&mut env, "eq_alias_a", s_type.clone(), alias1_ref.clone());
    add_def(&mut env, "eq_alias_b", s_type, alias1_ref);

    let tc = TypeChecker::new(&env);

    let proj_a = Expr::proj(
        s_name.clone(),
        0,
        Expr::const_(Name::from_string("eq_alias_a"), vec![]),
    );
    let proj_b = Expr::proj(
        s_name,
        0,
        Expr::const_(Name::from_string("eq_alias_b"), vec![]),
    );

    // Track WHNF calls to verify early exit
    tc.reset_whnf_impl_call_count_for_tests();
    assert!(
        tc.is_def_eq(&proj_a, &proj_b),
        "Proj(S, 0, alias_a) =?= Proj(S, 0, alias_b) should succeed in one delta step"
    );
    let whnf_calls = tc.whnf_impl_call_count_for_tests();
    assert!(
        whnf_calls < 20,
        "Expected fewer than 20 WHNF calls for equal-alias projections, got {whnf_calls}"
    );
}
